import{_ as i,C as s,o as l,c as h,j as d,a as e,E as r,ah as o}from"./chunks/framework.DuX8SFU5.js";const S=JSON.parse('{"title":"AM_JOYSTICK — руководство пользователя","description":"","frontmatter":{"pdf":"/pdf/AM_JOYSTICK_user_guide.pdf"},"headers":[],"relativePath":"am_joystick/user-guide.md","filePath":"am_joystick/user-guide.md"}'),_={name:"am_joystick/user-guide.md"};function n(c,t,p,b,m,u){const a=s("AssetImage");return l(),h("div",null,[t[0]||(t[0]=d("h1",{id:"am-joystick-—-руководство-пользователя",tabindex:"-1"},[e("AM_JOYSTICK — руководство пользователя "),d("a",{class:"header-anchor",href:"#am-joystick-—-руководство-пользователя","aria-label":'Permalink to "AM_JOYSTICK — руководство пользователя"'},"​")],-1)),t[1]||(t[1]=d("p",null,"Пульт с двумя джойстиками, который подключается к компьютеру по USB.",-1)),t[2]||(t[2]=d("h2",{id:"состав",tabindex:"-1"},[e("Состав "),d("a",{class:"header-anchor",href:"#состав","aria-label":'Permalink to "Состав"'},"​")],-1)),r(a,{name:"am_joystick_usb_kit.webp",alt:"Пульт: левый и правый джойстики, между ними плата AM_NODE_V2"}),t[3]||(t[3]=o('<table tabindex="0"><thead><tr><th>Узел</th><th>Что делает</th></tr></thead><tbody><tr><td>Левый <a href="./">AM_JOYSTICK</a></td><td>Шлёт положение ручки и кнопок в шину CAN</td></tr><tr><td>Правый <a href="./">AM_JOYSTICK</a></td><td>То же для правой ручки</td></tr><tr><td><a href="./../am_node_v2/">AM_NODE_V2</a> с прошивкой USB-джойстика</td><td>Собирает оба джойстика с шины CAN и отдаёт их компьютеру по USB</td></tr><tr><td>Сниффер CAN</td><td>Питает джойстики по шине CAN</td></tr></tbody></table><p>Джойстики и AM_NODE_V2 сидят на одной шине CAN внутри пульта и приходят настроенными.</p><h2 id="подключение" tabindex="-1">Подключение <a class="header-anchor" href="#подключение" aria-label="Permalink to &quot;Подключение&quot;">​</a></h2><ol><li>Подключить AM_NODE_V2 к компьютеру кабелем USB-C. От этого USB плата и питается.</li><li>Подключить сниффер к шине CAN пульта.</li><li>Подключить сниффер к любому источнику USB: зарядке или хабу с питанием. От него по шине CAN питаются оба джойстика.</li></ol><p>AM_NODE_V2 джойстики не питает, поэтому без сниффера они не работают. Схема питания временная, но проверенная.</p><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><p>Для компьютера пульт — обычный USB-джойстик (HID), драйвер не нужен. Windows, Linux и macOS видят игровой контроллер <code>AM USB joystick</code> (VID:PID <code>0483:5710</code>), браузер — через Gamepad API. Подойдёт любая программа, которая умеет работать с джойстиком.</p><h2 id="оси-и-кнопки" tabindex="-1">Оси и кнопки <a class="header-anchor" href="#оси-и-кнопки" aria-label="Permalink to &quot;Оси и кнопки&quot;">​</a></h2><p>Номера — как в системе. В Gamepad API индекс на единицу меньше: ось 1 — <code>axes[0]</code>, кнопка 1 — <code>buttons[0]</code>.</p><table tabindex="0"><thead><tr><th>Ось</th><th>Что</th><th>Знак</th></tr></thead><tbody><tr><td>1, X</td><td>левая ручка, влево-вправо</td><td>вправо — плюс</td></tr><tr><td>2, Y</td><td>левая ручка, вперёд-назад</td><td>вперёд — минус</td></tr><tr><td>3, Z</td><td>левый ролик</td><td>вверх — плюс</td></tr><tr><td>4, Rx</td><td>правая ручка, влево-вправо</td><td>вправо — плюс</td></tr><tr><td>5, Ry</td><td>правая ручка, вперёд-назад</td><td>вперёд — минус</td></tr><tr><td>6, Rz</td><td>правый ролик</td><td>вверх — плюс</td></tr><tr><td>7, 8</td><td>не используются</td><td>всегда 0</td></tr></tbody></table><p>Оси от −1 до +1, в нейтрали около нуля. Y вперёд уходит в минус, как у любого игрового контроллера.</p><table tabindex="0"><thead><tr><th>Кнопка</th><th>Левый</th><th>Кнопка</th><th>Правый</th></tr></thead><tbody><tr><td>1</td><td>клавиша сбоку рукоятки</td><td>8</td><td>клавиша сбоку рукоятки</td></tr><tr><td>2</td><td>верхняя красная кнопка</td><td>9</td><td>верхняя красная кнопка</td></tr><tr><td>3</td><td>нижняя красная кнопка</td><td>10</td><td>нижняя красная кнопка</td></tr><tr><td>4</td><td>ручка влево</td><td>11</td><td>ручка влево</td></tr><tr><td>5</td><td>ручка вправо</td><td>12</td><td>ручка вправо</td></tr><tr><td>6</td><td>ручка вперёд</td><td>13</td><td>ручка вперёд</td></tr><tr><td>7</td><td>ручка назад</td><td>14</td><td>ручка назад</td></tr></tbody></table><p>Кнопки 4–7 и 11–14 — контакты направления в самих джойстиках: замыкаются, как только ручка вышла из нейтрали. Кнопки 15 и 16 не используются.</p><h2 id="пример-панели" tabindex="-1">Пример панели <a class="header-anchor" href="#пример-панели" aria-label="Permalink to &quot;Пример панели&quot;">​</a></h2><p>Так пульт выглядит на нашей странице проверки: левая ручка вперёд и вправо, нажата левая боковая клавиша. Горят кнопки 1, 5 и 6, ось Y — в минусе. Страница в комплект не входит, её можно запросить.</p>',15)),r(a,{name:"am_joystick_dashboard.webp",alt:"Страница проверки: левая ручка вперёд и вправо, замкнуты контакты «вперёд» и «вправо», нажата боковая клавиша"}),t[4]||(t[4]=o('<h2 id="если-не-работает" tabindex="-1">Если не работает <a class="header-anchor" href="#если-не-работает" aria-label="Permalink to &quot;Если не работает&quot;">​</a></h2><ul><li>Компьютер не видит <code>AM USB joystick</code> — проверить кабель USB-C: нужен кабель с данными, а не только для зарядки.</li><li>Браузер не видит джойстик — подвигать ручку: до первого действия браузер джойстик не показывает.</li><li>Оси и кнопки одного джойстика стоят ровно в нуле и не реагируют — джойстик без питания или без связи. Пропавший джойстик через 0,5 с встаёт в ноль. Проверить сниффер и его USB.</li></ul><p>Технические подробности — в даташитах <a href="./datasheet">AM_JOYSTICK</a> и <a href="./../am_node_v2/datasheet#usb-joystick">AM_NODE_V2</a>.</p>',3))])}const f=i(_,[["render",n]]);export{S as __pageData,f as default};
